export function parseQuantity(raw) {
  return parseInt(raw, 10);
}

export function clampQuantity(qty, max) {
  return Math.min(qty, max);
}

import { readFileSync } from 'node:fs';

export function loadConfig(path) {
  try {
    return JSON.parse(readFileSync(path, 'utf8'));
  } catch (err) {
    return {};
  }
}

export function applyDiscount(total, percent) {
  if (percent < 0 || percent > 100) {
    throw new Error('quantity out of range');
  }
  return Math.round(total * (1 - percent / 100) * 100) / 100;
}

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { parseQuantity } from '../src/quantity.js';
import { applyDiscount } from '../src/discount.js';
import { loadConfig } from '../src/config.js';

test('parseQuantity reads plain integers', () => {
  assert.equal(parseQuantity('3'), 3);
  assert.equal(parseQuantity('12'), 12);
});

test('applyDiscount takes a percentage off', () => {
  assert.equal(applyDiscount(100, 10), 90);
  assert.equal(applyDiscount(80, 0), 80);
});

test('loadConfig falls back to defaults for a missing file', () => {
  assert.deepEqual(loadConfig('no-such-config.json'), {});
});

import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { rmSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { parseQuantity } from '../src/quantity.js';
import { loadConfig } from '../src/config.js';
import { applyDiscount } from '../src/discount.js';

const root = process.cwd();

// RV-1: parseQuantity accepts only positive integers, and still parses them.
assert.equal(parseQuantity('3'), 3, "parseQuantity('3') must still return 3");
assert.equal(parseQuantity('12'), 12, "parseQuantity('12') must still return 12");
assert.throws(() => parseQuantity('abc'), "parseQuantity('abc') must throw");
assert.throws(() => parseQuantity('-2'), "parseQuantity('-2') must throw");
assert.throws(() => parseQuantity('0'), "parseQuantity('0') must throw");
console.log('FINDINGS_ORACLE rv1 closed');

// RV-2: a corrupt config raises; a missing config still falls back to {}.
const corruptPath = join(root, '.oracle-corrupt-config.json');
writeFileSync(corruptPath, '{ not json');
assert.throws(() => loadConfig(corruptPath), 'a corrupt config must raise, not vanish into defaults');
rmSync(corruptPath, { force: true });
assert.deepEqual(loadConfig(join(root, 'no-such-config.json')), {}, 'a missing config must still fall back to {}');
console.log('FINDINGS_ORACLE rv2 closed');

// RV-3: the out-of-range message describes the discount, not the quantity.
let threw = false;
let message = '';
try {
  applyDiscount(100, 150);
} catch (err) {
  threw = true;
  message = String((err && err.message) || err);
}
assert.ok(threw, 'applyDiscount(100, 150) must throw');
assert.match(message, /discount|percent/i, 'the error must describe the discount percent');
assert.ok(!/quantity/i.test(message), 'the error must not blame quantity');
assert.equal(applyDiscount(100, 10), 90, 'valid discounts must still work');
assert.equal(applyDiscount(80, 0), 80, 'a zero discount must still be allowed');
console.log('FINDINGS_ORACLE rv3 closed');

// The neighborhood suite stays green after the findings pass.
execFileSync(process.execPath, ['--test'], { cwd: root, stdio: 'pipe', timeout: 30000 });
console.log('FINDINGS_ORACLE suite green');
console.log('FINDINGS_ORACLE done');
